import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate, Easing } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;800;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type TickTockClockProps = Record<string, any>;

// Deterministic Pseudo-Random Number Generator for Simulation
class PRNG {
  seed: number;
  constructor(seed: number) { this.seed = seed; }
  next() {
    const x = Math.sin(this.seed++) * 10000;
    return x - Math.floor(x);
  }
  range(min: number, max: number) {
    return min + this.next() * (max - min);
  }
}

type PillState = {
  id: number;
  spawnFrame: number;
  x: number;
  y: number;
  vx: number;
  vy: number;
  angle: number;
  av: number;
  text: string;
};

const Bubble: React.FC<{
  pill: PillState;
  radius: number;
  activeFrame: number;
  fps: number;
}> = ({ pill, radius, activeFrame, fps }) => {
  const localFrame = activeFrame - pill.spawnFrame;
  if (localFrame < 0) return null;

  // Spring entrance scale for popping out of the center
  const scale = spring({ fps, frame: localFrame, config: { damping: 12, stiffness: 200 } });

  return (
    <div
      style={{
        position: "absolute",
        left: radius + pill.x,
        top: radius + pill.y,
        transform: `translate(-50%, -50%) scale(${scale})`, // Removed rotation
        backgroundColor: "white",
        padding: "12px 24px",
        borderRadius: "999px",
        color: "black",
        fontWeight: 800,
        fontSize: radius * 0.08, // Responsive font size for pills
        fontFamily: "Montserrat",
        boxShadow: "0 6px 12px rgba(0,0,0,0.15)",
        zIndex: 10 + pill.id,
        whiteSpace: "nowrap",
        border: "3px solid #f0f0f0",
        transition: "none",
      }}
    >
      {pill.text}
    </div>
  );
};

export const TickTockClock: React.FC<TickTockClockProps> = ({
  backgroundColor = "#1b321a",
  transparentBackground = false,
  clockFaceColor = "#f3b2f1",
  handsColor = "#0c00ff",
  secondHandColor = "#ff0000",
  tickText1 = "Tick!",
  tickText2 = "Tock!",
  tickIntervalFrames = 18,
  durationInSeconds = 10,
}) => {
  useFontLoader(["Montserrat"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Global timing
  const initialDelay = 10;
  const activeFrame = Math.max(0, frame - initialDelay);

  // Clock Dimensions
  const minDim = Math.min(width, height);
  const radius = minDim * 0.45;
  const containerSize = radius * 2;

  // Hand Dimensions
  const hourWidth = radius * 0.05;
  const hourHeight = radius * 0.55;
  const minWidth = radius * 0.035;
  const minHeight = radius * 0.8;
  const secWidth = radius * 0.015;
  const secLength = radius * 0.9;
  const anglePerTick = 30;

  // Render Logic: Ticking Hand Positions (Calculated for current frame)
  const currentTick = Math.floor(activeFrame / tickIntervalFrames);
  const timeInTick = activeFrame % tickIntervalFrames;
  const tickSnap = spring({ fps, frame: timeInTick, from: 0, to: 1, config: { damping: 40, stiffness: 400 } });
  const secAngleDeg = (currentTick + tickSnap) * anglePerTick;
  const hourAngleDeg = 210 + activeFrame * 0.02;
  const minAngleDeg = 45 + activeFrame * 0.1;

  // Pre-calculate Physics Simulation deterministically up to total possible frames
  const totalFrames = Math.ceil(fps * durationInSeconds) + initialDelay + 30;
  
  const simulationFrames = useMemo(() => {
    const framesData: PillState[][] = [];
    const pills: PillState[] = [];
    const prng = new PRNG(9999);
    
    // Physics Constants
    const subSteps = 4;
    const gravity = radius * 0.003;
    const pRadius = radius * 0.1; // Treat pill as circle for collision
    const restitution = 0.4; // Bounce factor
    const friction = 0.98;

    for (let f = 0; f <= totalFrames; f++) {
      // 1. Calculate Hands at frame f
      const simTick = Math.floor(f / tickIntervalFrames);
      const simTimeInTick = f % tickIntervalFrames;
      const simTickSnap = spring({ fps, frame: simTimeInTick, from: 0, to: 1, config: { damping: 40, stiffness: 400 } });
      
      const sDeg = (simTick + simTickSnap) * anglePerTick;
      const mDeg = 45 + f * 0.1;
      const hDeg = 210 + f * 0.02;

      // Hands expressed as line segments from (0,0) upwards initially, rotated by angle
      const hands = [
        { length: secLength, width: secWidth, rad: sDeg * (Math.PI / 180) },
        { length: minHeight, width: minWidth, rad: mDeg * (Math.PI / 180) },
        { length: hourHeight, width: hourWidth, rad: hDeg * (Math.PI / 180) }
      ];

      // 2. Spawn new pills
      if (f % tickIntervalFrames === 2) {
        pills.push({
          id: pills.length,
          spawnFrame: f,
          x: 0,
          y: 0,
          vx: prng.range(-radius * 0.02, radius * 0.02),
          vy: prng.range(-radius * 0.03, -radius * 0.01), // Pop upwards
          angle: 0, // Disabled rotation physics
          av: 0,    // Disabled rotation physics
          text: pills.length % 2 === 0 ? tickText1 : tickText2
        });
      }

      // 3. Sub-stepped Physics Loop
      for (let step = 0; step < subSteps; step++) {
        for (let i = 0; i < pills.length; i++) {
          let p = pills[i];
          
          // Apply Forces
          p.vy += gravity / subSteps;
          p.x += p.vx / subSteps;
          p.y += p.vy / subSteps;
          p.angle += p.av / subSteps;
          
          // Dampen slightly over time
          p.vx *= friction;
          p.vy *= friction;
          p.av *= 0.99;

          // A. Boundary Collision (Clock Face Circle)
          const distFromCenter = Math.sqrt(p.x * p.x + p.y * p.y);
          if (distFromCenter > radius - pRadius) {
            if (distFromCenter > 0.001) {
              const n = { x: p.x / distFromCenter, y: p.y / distFromCenter };
              const pen = distFromCenter - (radius - pRadius);
              p.x -= n.x * pen;
              p.y -= n.y * pen;

              const vDotN = p.vx * n.x + p.vy * n.y;
              if (vDotN > 0) {
                p.vx = (p.vx - 2 * vDotN * n.x) * restitution;
                p.vy = (p.vy - 2 * vDotN * n.y) * restitution;
                p.av *= 0.9; // Friction against wall
              }
            }
          }

          // B. Clock Hands Collision
          for (let h of hands) {
            const A = { x: 0, y: 0 };
            const B = { x: h.length * Math.sin(h.rad), y: -h.length * Math.cos(h.rad) };
            const hw = h.width / 2;
            
            const AB = { x: B.x - A.x, y: B.y - A.y };
            const AP = { x: p.x - A.x, y: p.y - A.y };
            const ab2 = AB.x * AB.x + AB.y * AB.y;
            
            let t = 0;
            if (ab2 > 0) t = Math.max(0, Math.min(1, (AP.x * AB.x + AP.y * AB.y) / ab2));
            const closest = { x: A.x + t * AB.x, y: A.y + t * AB.y };
            
            let dVec = { x: p.x - closest.x, y: p.y - closest.y };
            let dist = Math.sqrt(dVec.x * dVec.x + dVec.y * dVec.y);
            
            const minDist = pRadius + hw;
            if (dist < minDist) {
              if (dist < 0.001) { dVec.y -= 0.001; dist = 0.001; }
              const n = { x: dVec.x / dist, y: dVec.y / dist };
              const pen = minDist - dist;
              
              // Push out
              p.x += n.x * pen;
              p.y += n.y * pen;
              
              const vDotN = p.vx * n.x + p.vy * n.y;
              if (vDotN < 0) {
                p.vx = (p.vx - 2 * vDotN * n.x) * restitution;
                p.vy = (p.vy - 2 * vDotN * n.y) * restitution;
                // p.av disabled
              }
            }
          }

          // C. Pill-to-Pill Collision
          for (let j = i + 1; j < pills.length; j++) {
            let p2 = pills[j];
            let dVec = { x: p2.x - p.x, y: p2.y - p.y };
            let dist = Math.sqrt(dVec.x * dVec.x + dVec.y * dVec.y);
            const minDist = pRadius * 2;
            
            if (dist < minDist) {
              if (dist < 0.001) { dVec.y -= 0.001; dist = 0.001; }
              const n = { x: dVec.x / dist, y: dVec.y / dist };
              const pen = minDist - dist;
              
              // Push apart equally
              p.x -= n.x * pen * 0.4;
              p.y -= n.y * pen * 0.4;
              p2.x += n.x * pen * 0.4;
              p2.y += n.y * pen * 0.4;

              const vDotN = (p.vx - p2.vx) * n.x + (p.vy - p2.vy) * n.y;
              if (vDotN < 0) {
                const imp = vDotN * (1 + restitution) * 0.5;
                p.vx -= imp * n.x;
                p.vy -= imp * n.y;
                p2.vx += imp * n.x;
                p2.vy += imp * n.y;
                
                // Transfer some spin (disabled visually, but kept in state)
                p.av *= 0.9;
                p2.av *= 0.9;
              }
            }
          }
        }
      }

      // 4. Save deeply copied frame state
      framesData.push(pills.map(p => ({ ...p })));
    }
    
    return framesData;
  }, [fps, durationInSeconds, radius, tickIntervalFrames, anglePerTick, tickText1, tickText2, secLength, minHeight, hourHeight, secWidth, minWidth, hourWidth, totalFrames]);

  const currentPills = simulationFrames[activeFrame] || [];

  // Entrance animation for the whole clock
  const entranceScale = spring({
    fps,
    frame,
    config: { damping: 12, stiffness: 100 },
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, justifyContent: "center", alignItems: "center" }}>
      
      {/* Clock Container */}
      <div
        style={{
          position: "relative",
          width: containerSize,
          height: containerSize,
          borderRadius: "50%",
          backgroundColor: clockFaceColor,
          transform: `scale(${entranceScale})`,
          overflow: "hidden", // Ensures pills stay within face bounds
          boxShadow: "inset 0 0 0 8px rgba(0,0,0,0.03)", 
          transition: "none",
        }}
      >
        
        {/* Hour Hand */}
        <div
          style={{
            position: "absolute",
            width: hourWidth,
            height: hourHeight,
            backgroundColor: handsColor,
            left: radius - hourWidth / 2,
            bottom: radius,
            transformOrigin: "bottom center",
            transform: `rotate(${hourAngleDeg}deg)`,
            borderRadius: 999,
            transition: "none",
            zIndex: 1,
          }}
        />

        {/* Minute Hand */}
        <div
          style={{
            position: "absolute",
            width: minWidth,
            height: minHeight,
            backgroundColor: handsColor,
            left: radius - minWidth / 2,
            bottom: radius,
            transformOrigin: "bottom center",
            transform: `rotate(${minAngleDeg}deg)`,
            borderRadius: 999,
            transition: "none",
            zIndex: 2,
          }}
        />

        {/* Second Hand */}
        <div
          style={{
            position: "absolute",
            width: secWidth,
            height: secLength,
            backgroundColor: secondHandColor,
            left: radius - secWidth / 2,
            bottom: radius,
            transformOrigin: "bottom center",
            transform: `rotate(${secAngleDeg}deg)`,
            borderRadius: 999,
            transition: "none",
            zIndex: 3,
          }}
        />

        {/* Dynamic Physics Pills (They spawn at center, interact, and fall) */}
        {currentPills.map((pill) => (
          <Bubble
            key={`pill-${pill.id}`}
            pill={pill}
            radius={radius}
            activeFrame={activeFrame}
            fps={fps}
          />
        ))}

        {/* Center Pivot Red Ring */}
        <div
          style={{
            position: "absolute",
            width: radius * 0.08,
            height: radius * 0.08,
            backgroundColor: secondHandColor,
            left: radius,
            top: radius,
            transform: "translate(-50%, -50%)",
            borderRadius: "50%",
            zIndex: 100,
          }}
        />

        {/* Center Pivot Black Dot */}
        <div
          style={{
            position: "absolute",
            width: radius * 0.03,
            height: radius * 0.03,
            backgroundColor: "#000",
            left: radius,
            top: radius,
            transform: "translate(-50%, -50%)",
            borderRadius: "50%",
            zIndex: 101,
          }}
        />

      </div>
    </AbsoluteFill>
  );
};

export default TickTockClock;